        }

        // add the actual content to the scroll view
        setDialogTitle(getRealActivity().getViewTitle());

        if (getChildFragmentManager().findFragmentByTag(TAG_CONTENT_FRAGMENT) == null)
            getChildFragmentManager().beginTransaction()
                    .replace(R.id.content_scroll_view, mContentFragment, TAG_CONTENT_FRAGMENT)
                    .commit();

        initToolbar(view);

        return view;
    }

    public void setTitle(int resId) {
        mTitleId = resId;
    }

    @Override
    public void onAttach(Context context) {
        super.onAttach(context);

        // make sure the container activity has implemented the callback interface
        try {
            mCallbacks = (InteractionListener)context;
        } catch (ClassCastException e) {
            throw new ClassCastException(context.toString() + " must implement ManageFragment.InteractionListener");
        }
    }

    @Override
    public void onDetach() {
        super.onDetach();
        mCallbacks = null;
    }

    /**
     * Iterates over all children fragments.
     */
    private interface ChildFragmentIterationListener {
        void callMethod(Fragment fragment);
    }

    private void iterateChildFragments(ChildFragmentIterationListener callbacks) {
        List<Fragment> fragments = getChildFragmentManager().getFragments();
        if (fragments != null)
            for (Fragment fragment : fragments)
                if (fragment != null)
                    callbacks.callMethod(fragment);
    }

    /**
     * Required as an Android bug workaround. {@link Fragment#onRequestPermissionsResult(int, String[], int[])}
     * calls aren't passed to child fragments.
     */
    @Override
    public void onRequestPermissionsResult(final int requestCode, @NonNull final String[] permissions, @NonNull final int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);

        iterateChildFragments(new ChildFragmentIterationListener() {
            @Override
            public void callMethod(Fragment fragment) {
                fragment.onRequestPermissionsResult(requestCode, permissions, grantResults);
            }
        });
    }

    /**
     * Required as an Android bug workaround. {@link Fragment#onActivityResult(int, int, Intent)}
     * calls aren't passed to child fragments.
     */
    @Override
    public void onActivityResult(final int requestCode, final int resultCode, final Intent data) {
        super.onActivityResult(requestCode, resultCode, data);

        iterateChildFragments(new ChildFragmentIterationListener() {
            @Override
            public void callMethod(Fragment fragment) {
                fragment.onActivityResult(requestCode, resultCode, data);
            }
        });
    }

    @Override
    public void onCreateOptionsMenu(Menu menu, MenuInflater inflater) {
        super.onCreateOptionsMenu(menu, inflater);

        if (isVisible()) {
            menu.clear();
            inflater.inflate(R.menu.menu_done, menu);
        }
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        if (item.getItemId() == R.id.action_confirm) {
            onClickSave();
            return true;
        }

        return super.onOptionsItemSelected(item);
    }

    public void setContentFragment(ManageContentFragment contentFragment) {
        mContentFragment = contentFragment;
    }

    public ManageContentFragment getContentFragment() {
        return mContentFragment;
    }

    public LayoutSpecActivity getRealActivity() {
        return (LayoutSpecActivity)getActivity();
    }

    private void setDialogTitle(String title) {
        Dialog dialog = getDialog();
        if (dialog != null)
            dialog.setTitle(title);
    }

    private boolean closeDialog() {
        Dialog dialog = getDialog();
        if (dialog != null) {
            dialog.dismiss();
            return true;
        }
        return false;
    }

    private void onClickSave() {
        if (mContentFragment.addObjectToLogbook()) {
            mCallbacks.onManageDismiss(closeDialog());
            mContentFragment.onDismiss();
        }
    }

    private void initToolbar(View view) {
        LinearLayout toolbar = (LinearLayout)view.findViewById(R.id.toolbar_view);

        // if not shown as a dialog, hide the toolbar as the actual activity's toolbar is used
        if (getDialog() == null) {
            toolbar.setVisibility(View.GONE);
            return;
        }

        TextView title = (TextView)view.findViewById(R.id.title_text_view);
        title.setText(mTitleId == -1 ? getRealActivity().getViewTitle() : getResources().getString(mTitleId));

        ImageButton saveButton = (ImageButton)view.findViewById(R.id.done_button);
        saveButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                onClickSave();
            }
        });

        ImageButton backButton = (ImageButton)view.findViewById(R.id.back_button);
        backButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                closeDialog();
            }
        });
    }
}

package com.cohenadair.anglerslog.model.user_defines;

import android.content.ContentValues;
import android.content.Context;
import android.content.Intent;
import android.support.annotation.NonNull;
import android.util.Log;

import com.cohenadair.anglerslog.model.Logbook;
import com.cohenadair.anglerslog.model.backup.Json;
import com.cohenadair.anglerslog.utilities.Utils;

import org.json.JSONException;
import org.json.JSONObject;

import java.util.UUID;

import static com.cohenadair.anglerslog.database.LogbookSchema.UserDefineTable;

/**
 * A UserDefineObject is the superclass for all "user defined" data such as species and locations.
 * @author Cohen Adair
 */
public class UserDefineObject {

    private static final String TAG = "UserDefineObject";

    private UUID mId;
    private String mName;
    private boolean mShouldDelete; // toggled on UI selection for deleting multiple items
    private boolean mIsSelected; // used to show selection in RecyclerView layouts

    public UserDefineObject(String name) {
        mId = UUID.randomUUID();
        mName = name;
    }

    public UserDefineObject(String name, UUID id) {
        mId = id;
        mName = name;
    }

    public UserDefineObject(UserDefineObject obj) {
        initFromObj(obj, false);
    }

    public UserDefineObject(UserDefineObject obj, boolean keepId) {
        initFromObj(obj, keepId);
    }

    public UserDefineObject(JSONObject jsonObject) {
        // importing from iOS will not have an id property
        try {
            mId = UUID.fromString(jsonObject.getString(Json.ID));
        } catch (JSONException e) {
            Log.e(TAG, "No JSON value for " + Json.ID);
            mId = UUID.randomUUID();
        }

        // importing from iOS will not have a name property for some subclasses
        try {
            mName = jsonObject.getString(Json.NAME);
        } catch (JSONException e) {
            Log.e(TAG, "No JSON value for " + Json.NAME);
            mName = getIdAsString();
        }
    }

    private void initFromObj(UserDefineObject obj, boolean keepId) {
        if (obj != null) {
            mId = keepId ? obj.getId() : UUID.randomUUID();
            mName = obj.getName();
            mShouldDelete = obj.getShouldDelete();
            mIsSelected = obj.getIsSelected();
        }
    }

    //region Getters & Setters
    public UUID getId() {
        return mId;
    }

    public void setId(UUID id) {
        mId = id;
    }

    public String getName() {
        return mName;
    }

    public void setName(String name) {
        mName = (name == null || name.equals("")) ? null : name;
    }

    public boolean getShouldDelete() {
        return mShouldDelete;
    }

    public void setShouldDelete(boolean shouldDelete) {
        mShouldDelete = shouldDelete;
    }

    public boolean getIsSelected() {
        return mIsSelected;
    }

    public void setIsSelected(boolean isSelected) {
        mIsSelected = isSelected;
    }
    //endregion

    public void removeDatabaseProperties() {
        // if needed, should be overridden by subclasses
    }

    public final String getNameAsString() {
        return (mName == null) ? "" : mName;
    }

    public String getDisplayName() {
        return mName;
    }

    @NonNull
    public final String getIdAsString() {
        return mId.toString();
    }

    public String toString() {
        return (mName == null) ? super.toString() : getDisplayName();
    }

    public boolean isNameNull() {
        return mName == null || mName.equals("");
    }

    /**
     * @return An intent filled with extras of information that can be shared. This method should be
     *         overridden by subclasses that can be shared.
     */
    public Intent getShareIntent(Context context) {
        Intent intent = new Intent(Intent.ACTION_SEND);
        intent.putExtra(Intent.EXTRA_TEXT, Logbook.getShareText(context));
        intent.setType(Utils.MIME_TYPE_IMAGE);
        return intent;
    }

    /**
     * Gets a {@link ContentValues} object for this UserDefineObject. This is used to save and
     * retrieve data from the backed SQLite database. Subclasses should override this method.
     *
     * @return A {@link ContentValues} object of this UserDefineObject.
     */
    public ContentValues getContentValues() {
        ContentValues values = new ContentValues();

        values.put(UserDefineTable.Columns.ID, getIdAsString());
        values.put(UserDefineTable.Columns.NAME, mName);
        values.put(UserDefineTable.Columns.SELECTED, mIsSelected);

        return values;
    }

    /**
     * Gets a {@link JSONObject} representation of this UserDefineObject. This is used for
     * {@link com.cohenadair.anglerslog.model.Logbook} exporting and importing. Subclasses should
     * override and call this method.
     *
     * @return A {@link JSONObject} of this UserDefineObject.
     * @throws JSONException Throws JSONException if the {@link JSONObject} cannot be created.
     */
    public JSONObject toJson() throws JSONException {
        JSONObject json = new JSONObject();

        json.put(Json.NAME, getNameAsString());
        json.put(Json.ID, getIdAsString());

        return json;
    }

    /**
     * Converts the current object into a String of keywords that can be used for searching.
     * Subclasses should override this class.
     *
     * @return A String representing different keywords for the current object.
     */
    public String toKeywordsString(Context context) {
        return appendToBuilder(new StringBuilder(), mName).toString();
    }

    /**
     * Adds a String value to the given {@link StringBuilder}.
     */
    protected StringBuilder appendToBuilder(StringBuilder builder, String value) {
        if (Utils.stringOrNull(value) == null)
            return builder;

        builder.append(value);
        builder.append(" ");

        return builder;
    }

    /**
     * Adds a float value to the given {@link StringBuilder}.
     */
    protected StringBuilder appendToBuilder(StringBuilder builder, float value) {
        if (value < 0)
            return builder;

        return appendToBuilder(builder, Float.toString(value));
    }

    /**
     * Adds a int value to the given {@link StringBuilder}.
     */
    protected StringBuilder appendToBuilder(StringBuilder builder, int value) {
        return appendToBuilder(builder, (float)value);
    }
}

package com.cohenadair.anglerslog.model.user_defines;

import android.content.Context;
import android.content.Intent;

import com.cohenadair.anglerslog.database.QueryHelper;
import com.cohenadair.anglerslog.database.cursors.FishingSpotCursor;
import com.cohenadair.anglerslog.database.cursors.UserDefineCursor;
import com.cohenadair.anglerslog.model.Logbook;
import com.cohenadair.anglerslog.model.backup.Json;
import com.cohenadair.anglerslog.model.backup.JsonExporter;
import com.cohenadair.anglerslog.model.utilities.HasCatchesInterface;
import com.cohenadair.anglerslog.model.utilities.UserDefineArrays;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.UUID;

import static com.cohenadair.anglerslog.database.LogbookSchema.FishingSpotTable;

/**
 * The Location object stores information on a single location, including many fishing spots
 * within that location.
 *
 * @author Cohen Adair
 */
public class Location extends UserDefineObject implements HasCatchesInterface {

    public Location() {
        this("");
    }

    public Location(String name) {
        super(name);
    }

    public Location(Location location, boolean keepId) {
        super(location, keepId);
    }

    public Location(UserDefineObject obj) {
        super(obj);
    }

    public Location(UserDefineObject obj, boolean keepId) {
        super(obj, keepId);
    }

    public Location(JSONObject jsonObject) throws JSONException {
        super(jsonObject);

        JSONArray fishingSpotsJson = jsonObject.getJSONArray(Json.FISHING_SPOTS);
        ArrayList<UserDefineObject> fishingSpots = new ArrayList<>();

        for (int i = 0; i < fishingSpotsJson.length(); i++)
            fishingSpots.add(new FishingSpot(fishingSpotsJson.getJSONObject(i)));

        setFishingSpots(fishingSpots);
    }

    //region Getters & Setters
    @Override
    public void setIsSelected(boolean isSelected) {
        super.setIsSelected(isSelected);
        Logbook.editLocation(getId(), this);
    }
    //endregion

    //region Fishing Spot Manipulation
    public ArrayList<UserDefineObject> getFishingSpots() {
        return QueryHelper.queryUserDefines(
                QueryHelper.queryUserDefines(
                        FishingSpotTable.NAME,
                        FishingSpotTable.Columns.LOCATION_ID + " = ?", new String[]{getIdAsString()}
                ),
                new QueryHelper.UserDefineQueryInterface() {
                    @Override
                    public UserDefineObject getObject(UserDefineCursor cursor) {
                        return new FishingSpotCursor(cursor).getFishingSpot();
                    }
                }
        );
    }

    /**
     * Resets the location's fishing spots by first removing the old ones, then adding the new ones.
     * @param newFishingSpots The new collection of {@link FishingSpot} objects.
     */
    public void setFishingSpots(ArrayList<UserDefineObject> newFishingSpots) {
        ArrayList<UserDefineObject> oldFishingSpots = getFishingSpots();

        for (UserDefineObject oldSpot : oldFishingSpots)
            removeFishingSpot(oldSpot.getId());

        for (UserDefineObject newSpot : newFishingSpots)
            addFishingSpot((FishingSpot)newSpot);
    }

    public boolean addFishingSpot(FishingSpot fishingSpot) {
        fishingSpot.setLocationId(getId());
        return QueryHelper.insertQuery(FishingSpotTable.NAME, fishingSpot.getContentValues(getId()));
    }

    public boolean removeFishingSpot(UUID id) {
        return QueryHelper.deleteUserDefine(FishingSpotTable.NAME, id);
    }

    public boolean removeAllFishingSpots() {
        ArrayList<UserDefineObject> fishingSpots = getFishingSpots();
        for (UserDefineObject spot : fishingSpots)
            if (!removeFishingSpot(spot.getId()))
                return false;

        return true;
    }

    public int getFishingSpotCount() {
        return QueryHelper.queryCount(FishingSpotTable.NAME, FishingSpotTable.Columns.LOCATION_ID + " = ?", new String[]{ getIdAsString() });
    }
    //endregion

    public ArrayList<UserDefineObject> getCatches() {
        ArrayList<UserDefineObject> catches = new ArrayList<>();
        ArrayList<UserDefineObject> spots = getFishingSpots();

        for (UserDefineObject obj : spots) {
            FishingSpot spot = (FishingSpot)obj;
            catches.addAll(spot.getCatches());
        }

        return catches;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public int getFishCaughtCount() {
        return QueryHelper.queryLocationCatchCount(this);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Intent getShareIntent(Context context) {
        Intent intent =  super.getShareIntent(context);

        String text = getDisplayName() + " has " + getFishingSpotCount() + " fishing spots and " + getFishCaughtCount() + " fish caught. ";
        intent.putExtra(Intent.EXTRA_TEXT, text + intent.getStringExtra(Intent.EXTRA_TEXT));

        return intent;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public JSONObject toJson() throws JSONException {
        JSONObject json = super.toJson();
        json.put(Json.FISHING_SPOTS, JsonExporter.getJsonArray(getFishingSpots()));
        return json;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String toKeywordsString(Context context) {
        return super.toKeywordsString(context) + UserDefineArrays.keywordsAsString(context, getFishingSpots());
    }
}

