// without configuration; $UIAB_OFFLINE_REPO overrides for run dirs elsewhere.
// The upstream URL is left in place below: harmless once the artifact resolves
// locally, and it documents where these came from.
buildscript {
    def uiabOfflineRepo = {
        def env = System.getenv('UIAB_OFFLINE_REPO')
        if (env) return new File(env)
        for (def d = buildscript.sourceFile.parentFile; d != null; d = d.parentFile) {
            for (def name : ['i_offline_repo', 'offline-repo']) {
                def candidate = new File(d, name)
                if (candidate.directory) return candidate
            }
        }
        return null
    }()

    repositories {
        if (uiabOfflineRepo != null) maven { url uiabOfflineRepo }
        maven { url 'https://maven.fabric.io/public' }
    }

    dependencies {
        classpath 'io.fabric.tools:gradle:1.31.2'
    }
}
